+:root{
+  --bg:#0a0a0a;
+  --panel:#0f0f10;
+  --panel2:#121214;
+  --text:#f5f5f5;
+  --muted:rgba(245,245,245,.72);
+  --faint:rgba(245,245,245,.12);
+  --faint2:rgba(245,245,245,.06);
+  --accent:#4f7dff;
+  --accent2:#ffb13d;
+  --danger:#ff4d4d;
+  --shadow: 0 20px 50px rgba(0,0,0,.55);
+  --radius:18px;
+  --radius2:26px;
+  --max:1160px;
+  --font: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji","Segoe UI Emoji";
+}
+
+*{box-sizing:border-box}
+html,body{height:100%}
+body{
+  margin:0;
+  font-family:var(--font);
+  background:
+    radial-gradient(1200px 600px at 15% -10%, rgba(79,125,255,.20), transparent 55%),
+    radial-gradient(900px 500px at 110% 12%, rgba(255,177,61,.12), transparent 60%),
+    radial-gradient(900px 650px at 55% 105%, rgba(79,125,255,.10), transparent 55%),
+    var(--bg);
+  color:var(--text);
+  line-height:1.5;
+  text-rendering:optimizeLegibility;
+}
+
+a{color:inherit; text-decoration:none}
+a:hover{color:var(--text)}
+
+.container{width:min(var(--max), calc(100% - 48px)); margin:0 auto}
+
+.skip{
+  position:absolute;
+  top:10px;
+  left:10px;
+  transform:translateY(-140%);
+  padding:10px 12px;
+  border:1px solid var(--faint);
+  border-radius:12px;
+  background:rgba(10,10,10,.9);
+}
+.skip:focus{transform:translateY(0); outline:none}
+
+/* Header */
+.site-header{position:sticky; top:0; z-index:60; backdrop-filter: blur(14px); background:rgba(10,10,10,.62); border-bottom:1px solid var(--faint)}
+.header-inner{display:flex; align-items:center; justify-content:space-between; gap:16px; padding:14px 0}
+.brand{display:flex; align-items:center; gap:12px}
+.logo-mark{
+  width:34px; height:34px; border-radius:10px;
+  background:linear-gradient(135deg, rgba(79,125,255,1), rgba(255,177,61,1));
+  box-shadow:0 14px 30px rgba(79,125,255,.18);
+}
+.brand strong{letter-spacing:.08em; font-weight:700; font-size:12px; text-transform:uppercase}
+.brand span{display:block; font-size:12px; color:var(--muted); margin-top:1px}
+
+.nav{display:flex; align-items:center; gap:18px}
+.nav a{
+  font-size:13px;
+  color:rgba(245,245,245,.78);
+  padding:8px 10px;
+  border-radius:10px;
+}
+.nav a:hover{background:rgba(245,245,245,.06); color:var(--text)}
+
+.header-actions{display:flex; align-items:center; gap:10px}
+.btn{
+  display:inline-flex; align-items:center; justify-content:center; gap:8px;
+  padding:10px 14px;
+  border-radius:999px;
+  border:1px solid var(--faint);
+  background:rgba(245,245,245,.05);
+  color:var(--text);
+  font-size:13px;
+  cursor:pointer;
+  transition:transform .18s ease, background .18s ease, border-color .18s ease;
+}
+.btn:hover{transform:translateY(-1px); background:rgba(245,245,245,.08); border-color:rgba(245,245,245,.18)}
+.btn-primary{background:linear-gradient(135deg, rgba(79,125,255,.95), rgba(79,125,255,.55)); border-color:rgba(79,125,255,.55)}
+.btn-primary:hover{background:linear-gradient(135deg, rgba(79,125,255,1), rgba(79,125,255,.7)); border-color:rgba(79,125,255,.9)}
+.btn-ghost{background:transparent}
+
+.menu-btn{display:none}
+
+.dropdown{position:relative}
+.dropdown-panel{
+  position:absolute;
+  right:0;
+  top:calc(100% + 10px);
+  width:240px;
+  padding:10px;
+  border-radius:16px;
+  border:1px solid var(--faint);
+  background:rgba(15,15,16,.95);
+  box-shadow:var(--shadow);
+  transform-origin: top right;
+  display:none;
+}
+.dropdown-panel[data-open="true"]{display:block; animation:pop .16s ease-out}
+@keyframes pop{from{transform:translateY(-6px) scale(.98); opacity:.0}to{transform:translateY(0) scale(1); opacity:1}}
+.dropdown-panel button{
+  width:100%;
+  text-align:left;
+  padding:10px 12px;
+  border-radius:12px;
+  border:0;
+  background:transparent;
+  color:rgba(245,245,245,.88);
+  cursor:pointer;
+  font-size:13px;
+}
+.dropdown-panel button:hover{background:rgba(245,245,245,.06); color:var(--text)}
+
+/* Hero */
+.hero{padding:44px 0 26px}
+.hero-grid{display:grid; grid-template-columns:1.05fr .95fr; gap:26px; align-items:stretch}
+.eyebrow{display:inline-flex; align-items:center; gap:10px; padding:8px 12px; border-radius:999px; border:1px solid var(--faint); background:rgba(245,245,245,.04); color:var(--muted); font-size:12px}
+.eyebrow .dot{width:8px; height:8px; border-radius:99px; background:var(--accent)}
+.h1{font-size:56px; line-height:1.02; letter-spacing:-.04em; margin:16px 0 10px}
+.lead{font-size:16px; color:var(--muted); max-width:52ch; margin:0 0 18px}
+.hero-actions{display:flex; gap:10px; flex-wrap:wrap}
+
+.hero-card{
+  border-radius:var(--radius2);
+  border:1px solid var(--faint);
+  background:linear-gradient(180deg, rgba(245,245,245,.06), rgba(245,245,245,.03));
+  box-shadow:var(--shadow);
+  overflow:hidden;
+  position:relative;
+}
+.hero-card::before{
+  content:"";
+  position:absolute;
+  inset:-2px;
+  background:radial-gradient(700px 260px at 20% 0%, rgba(79,125,255,.24), transparent 55%),
+             radial-gradient(700px 260px at 100% 40%, rgba(255,177,61,.14), transparent 55%);
+  pointer-events:none;
+}
+.hero-carousel{position:relative; padding:18px; min-height:340px}
+.hero-slide{
+  position:absolute;
+  inset:18px;
+  border-radius:22px;
+  border:1px solid rgba(245,245,245,.10);
+  background:
+    linear-gradient(180deg, rgba(10,10,10,.35), rgba(10,10,10,.75)),
+    radial-gradient(1200px 500px at 0% 0%, rgba(79,125,255,.22), transparent 50%),
+    radial-gradient(1000px 500px at 100% 0%, rgba(255,177,61,.14), transparent 55%),
+    var(--panel);
+  overflow:hidden;
+  padding:22px;
+  display:grid;
+  grid-template-rows:auto auto 1fr auto;
+  opacity:0;
+  transform:translateY(10px) scale(.99);
+  transition:opacity .5s ease, transform .5s ease;
+}
+.hero-slide[data-active="true"]{opacity:1; transform:translateY(0) scale(1)}
+.hero-kicker{display:flex; align-items:center; justify-content:space-between; gap:12px; color:var(--muted); font-size:12px}
+.pill{display:inline-flex; align-items:center; gap:8px; padding:8px 10px; border-radius:999px; border:1px solid rgba(245,245,245,.12); background:rgba(245,245,245,.05)}
+.pill .bar{width:12px; height:2px; background:var(--accent2); border-radius:4px}
+.hero-title{font-size:28px; margin:12px 0 8px; letter-spacing:-.02em; line-height:1.08}
+.hero-desc{color:rgba(245,245,245,.72); margin:0; max-width:60ch}
+.hero-cta-row{display:flex; align-items:center; justify-content:space-between; gap:12px; margin-top:16px}
+.hero-controls{display:flex; gap:8px}
+.icon-btn{
+  width:40px; height:40px;
+  border-radius:999px;
+  border:1px solid rgba(245,245,245,.16);
+  background:rgba(245,245,245,.06);
+  color:var(--text);
+  cursor:pointer;
+}
+.icon-btn:hover{background:rgba(245,245,245,.09)}
+.dots{display:flex; gap:8px}
+.dot-btn{width:9px; height:9px; border-radius:99px; border:1px solid rgba(245,245,245,.22); background:transparent; cursor:pointer}
+.dot-btn[aria-selected="true"]{background:var(--accent); border-color:rgba(79,125,255,.7)}
+
+/* Sections */
+section{padding:78px 0}
+.section-head{display:flex; align-items:flex-end; justify-content:space-between; gap:18px; margin-bottom:22px}
+.kicker{color:var(--muted); font-size:12px; letter-spacing:.12em; text-transform:uppercase}
+.h2{font-size:34px; letter-spacing:-.03em; margin:10px 0 0; line-height:1.1}
+.sub{color:var(--muted); margin:10px 0 0; max-width:66ch}
+
+.panel{
+  border-radius:var(--radius2);
+  border:1px solid var(--faint);
+  background:linear-gradient(180deg, rgba(245,245,245,.05), rgba(245,245,245,.025));
+}
+
+/* Team */
+.tabs{display:flex; gap:10px; flex-wrap:wrap}
+.tab{
+  padding:10px 14px;
+  border-radius:999px;
+  border:1px solid rgba(245,245,245,.14);
+  background:rgba(245,245,245,.04);
+  color:rgba(245,245,245,.78);
+  cursor:pointer;
+  font-size:13px;
+}
+.tab[aria-selected="true"]{background:rgba(79,125,255,.18); border-color:rgba(79,125,255,.48); color:var(--text)}
+
+.carousel-wrap{margin-top:18px}
+.scroller{
+  display:flex;
+  gap:14px;
+  overflow:auto;
+  scroll-snap-type:x mandatory;
+  -webkit-overflow-scrolling:touch;
+  padding:14px;
+  border-radius:var(--radius2);
+}
+.scroller::-webkit-scrollbar{height:10px}
+.scroller::-webkit-scrollbar-thumb{background:rgba(245,245,245,.14); border-radius:99px}
+.scroller::-webkit-scrollbar-track{background:rgba(245,245,245,.05); border-radius:99px}
+
+.card{
+  flex:0 0 auto;
+  width:360px;
+  scroll-snap-align:start;
+  border-radius:22px;
+  border:1px solid rgba(245,245,245,.12);
+  background:rgba(18,18,20,.75);
+  overflow:hidden;
+  box-shadow:0 18px 40px rgba(0,0,0,.45);
+}
+.card-media{position:relative; height:216px; overflow:hidden}
+.card-media img{width:100%; height:100%; object-fit:cover; filter:saturate(.9) contrast(1.06) brightness(.9)}
+.card-media::after{content:""; position:absolute; inset:0; background:linear-gradient(180deg, transparent 30%, rgba(10,10,10,.75))}
+.card-body{padding:16px 16px 18px}
+.card-title{display:flex; align-items:flex-start; justify-content:space-between; gap:12px}
+.card-title h3{margin:0; font-size:16px; letter-spacing:-.01em}
+.meta{color:var(--muted); font-size:12px; margin-top:6px}
+.quote{margin:12px 0 14px; color:rgba(245,245,245,.86); font-size:13px; line-height:1.5}
+.quote::before{content:"\201C"; color:rgba(255,177,61,.9); margin-right:2px}
+.quote::after{content:"\201D"; color:rgba(255,177,61,.9); margin-left:2px}
+
+.card-actions{display:flex; gap:10px; align-items:center; justify-content:space-between}
+.text-link{color:rgba(245,245,245,.86); font-size:13px}
+.text-link:hover{color:var(--accent)}
+
+.carousel-controls{display:flex; gap:10px; justify-content:flex-end; margin-top:10px}
+
+/* Work */
+.work-scroller .card{width:420px}
+.badge{display:inline-flex; align-items:center; gap:8px; padding:7px 10px; border-radius:999px; background:rgba(245,245,245,.06); border:1px solid rgba(245,245,245,.12); color:rgba(245,245,245,.78); font-size:12px}
+
+/* CTA banner */
+.cta{
+  padding:0;
+}
+.cta-inner{
+  border-radius:var(--radius2);
+  border:1px solid rgba(245,245,245,.12);
+  background:
+    radial-gradient(900px 320px at 0% 0%, rgba(79,125,255,.24), transparent 60%),
+    radial-gradient(900px 320px at 100% 10%, rgba(255,177,61,.18), transparent 60%),
+    rgba(18,18,20,.75);
+  box-shadow:var(--shadow);
+  padding:34px;
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap:18px;
+}
+.cta-inner h2{margin:0; font-size:28px; letter-spacing:-.02em}
+.cta-inner p{margin:8px 0 0; color:rgba(245,245,245,.78); max-width:70ch}
+
+/* Two-column section */
+.split{display:grid; grid-template-columns: 1.05fr .95fr; gap:22px; align-items:start}
+.callout{padding:22px; border-radius:22px; border:1px solid rgba(245,245,245,.12); background:rgba(18,18,20,.7)}
+.callout h3{margin:0 0 10px; font-size:16px}
+.callout p{margin:0; color:rgba(245,245,245,.72)}
+.stack{display:grid; gap:12px}
+
+/* Insights */
+.grid{
+  display:grid;
+  gap:14px;
+  grid-template-columns:repeat(12, 1fr);
+}
+.insight{
+  grid-column: span 4;
+  border-radius:22px;
+  border:1px solid rgba(245,245,245,.12);
+  background:rgba(18,18,20,.72);
+  overflow:hidden;
+  display:grid;
+  grid-template-rows:140px 1fr;
+  box-shadow:0 18px 40px rgba(0,0,0,.42);
+}
+.insight .thumb{position:relative}
+.insight .thumb img{width:100%; height:100%; object-fit:cover; filter:saturate(.92) contrast(1.05) brightness(.88)}
+.insight .thumb::after{content:""; position:absolute; inset:0; background:linear-gradient(180deg, transparent 30%, rgba(10,10,10,.72))}
+.insight .body{padding:14px 14px 16px}
+.insight h3{margin:8px 0 0; font-size:15px; letter-spacing:-.01em; line-height:1.2}
+.insight .row{display:flex; align-items:center; justify-content:space-between; gap:10px; margin-top:12px}
+
+/* Principles */
+.principles .card{width:auto}
+.principles-grid{display:grid; grid-template-columns:repeat(12, 1fr); gap:14px}
+.principle{grid-column:span 6; padding:18px; border-radius:22px; border:1px solid rgba(245,245,245,.12); background:rgba(18,18,20,.70)}
+.principle h3{margin:0; font-size:16px}
+.principle p{margin:10px 0 0; color:rgba(245,245,245,.74)}
+
+/* Footer */
+footer{padding:58px 0 70px; border-top:1px solid var(--faint)}
+.footer-top{display:grid; grid-template-columns:1fr 1fr; gap:14px; margin-bottom:26px}
+.footer-cta{padding:18px; border-radius:22px; border:1px solid rgba(245,245,245,.12); background:rgba(18,18,20,.7)}
+.footer-cta p{margin:0 0 12px; color:rgba(245,245,245,.76)}
+.footer-mid{display:flex; align-items:flex-start; justify-content:space-between; gap:18px; flex-wrap:wrap; padding-top:18px; border-top:1px solid var(--faint2)}
+.footer-links{display:flex; gap:14px; flex-wrap:wrap}
+.footer-links a{color:rgba(245,245,245,.72); font-size:13px; padding:8px 10px; border-radius:10px}
+.footer-links a:hover{background:rgba(245,245,245,.06); color:var(--text)}
+.legal{color:rgba(245,245,245,.55); font-size:12px}
+
+/* Cookie */
+.cookie{
+  position:fixed;
+  left:14px;
+  right:14px;
+  bottom:14px;
+  z-index:80;
+  display:none;
+}
+.cookie[data-open="true"]{display:block}
+.cookie-inner{
+  margin:0 auto;
+  width:min(var(--max), 100%);
+  border-radius:22px;
+  border:1px solid rgba(245,245,245,.14);
+  background:rgba(15,15,16,.92);
+  box-shadow:var(--shadow);
+  padding:16px;
+  display:flex;
+  align-items:flex-start;
+  justify-content:space-between;
+  gap:14px;
+}
+.cookie p{margin:0; color:rgba(245,245,245,.76); font-size:13px; max-width:72ch}
+.cookie-actions{display:flex; gap:10px; flex-wrap:wrap; justify-content:flex-end}
+
+.modal-backdrop{
+  position:fixed;
+  inset:0;
+  background:rgba(0,0,0,.55);
+  z-index:90;
+  display:none;
+}
+.modal-backdrop[data-open="true"]{display:block}
+.modal{
+  position:fixed;
+  left:50%;
+  top:50%;
+  transform:translate(-50%,-50%);
+  width:min(720px, calc(100% - 28px));
+  border-radius:22px;
+  border:1px solid rgba(245,245,245,.14);
+  background:rgba(15,15,16,.96);
+  box-shadow:var(--shadow);
+  z-index:100;
+  display:none;
+}
+.modal[data-open="true"]{display:block; animation:pop .16s ease-out}
+.modal header{padding:16px 16px 0}
+.modal h3{margin:0; font-size:16px}
+.modal .content{padding:12px 16px 16px; color:rgba(245,245,245,.74)}
+.modal .toggles{display:grid; gap:10px; margin:12px 0 0}
+.toggle{display:flex; align-items:center; justify-content:space-between; gap:12px; padding:12px 12px; border-radius:16px; border:1px solid rgba(245,245,245,.12); background:rgba(245,245,245,.04)}
+.toggle label{font-size:13px}
+.toggle input{width:44px; height:24px}
+.modal footer{padding:0 16px 16px; display:flex; justify-content:flex-end; gap:10px}
+
+/* Mobile */
+@media (max-width: 960px){
+  .hero-grid{grid-template-columns:1fr;}
+  .h1{font-size:46px}
+  .split{grid-template-columns:1fr}
+  .insight{grid-column:span 6}
+}
+@media (max-width: 720px){
+  .container{width:calc(100% - 28px)}
+  section{padding:64px 0}
+  .h1{font-size:40px}
+  .h2{font-size:30px}
+  .nav{display:none}
+  .menu-btn{display:inline-flex}
+  .footer-top{grid-template-columns:1fr}
+  .insight{grid-column:span 12}
+  .principle{grid-column:span 12}
+  .card{width:305px}
+  .work-scroller .card{width:340px}
+  .cta-inner{flex-direction:column; align-items:flex-start}
+  .carousel-controls{justify-content:flex-start}
+}
+
+@media (prefers-reduced-motion: reduce){
+  *{scroll-behavior:auto !important; transition:none !important; animation:none !important}
+}
+
*** End Patch
PATCH

