const fs = require('fs');
const path = require('path');

function clamp(x, a, b) { return x < a ? a : x > b ? b : x; }

function writePPM(filePath, w, h, pixels) {
  const header = Buffer.from(`P6\n${w} ${h}\n255\n`, 'ascii');
  const body = Buffer.alloc(w * h * 3);
  for (let i = 0; i < w * h; i++) {
    const [r, g, b] = pixels[i];
    body[i * 3 + 0] = r;
    body[i * 3 + 1] = g;
    body[i * 3 + 2] = b;
  }
  fs.writeFileSync(filePath, Buffer.concat([header, body]));
}

function mulberry32(seed) {
  let t = seed >>> 0;
  return () => {
    t += 0x6D2B79F5;
    let x = t;
    x = Math.imul(x ^ (x >>> 15), x | 1);
    x ^= x + Math.imul(x ^ (x >>> 7), x | 61);
    return ((x ^ (x >>> 14)) >>> 0) / 4294967296;
  };
}

function renderAbstract(w, h, seed) {
  const rnd = mulberry32(seed);
  const base = [12, 12, 14];
  const a1 = [79, 125, 255];
  const a2 = [255, 177, 61];

  function rand(min, max) { return min + (max - min) * rnd(); }

  const orbs = [
    { cx: rand(0.12, 0.42) * w, cy: rand(0.05, 0.28) * h, r: rand(0.32, 0.55) * Math.min(w, h), col: a1, amp: 0.90 },
    { cx: rand(0.65, 1.04) * w, cy: rand(0.04, 0.22) * h, r: rand(0.26, 0.48) * Math.min(w, h), col: a2, amp: 0.72 },
    { cx: rand(0.30, 0.90) * w, cy: rand(0.76, 1.05) * h, r: rand(0.34, 0.62) * Math.min(w, h), col: [120, 120, 120], amp: 0.28 }
  ];

  const pixels = new Array(w * h);

  for (let y = 0; y < h; y++) {
    const t = y / (h - 1);
    const br = Math.round(base[0] * (1 - t) + 10 * t);
    const bg = Math.round(base[1] * (1 - t) + 10 * t);
    const bb = Math.round(base[2] * (1 - t) + 12 * t);

    for (let x = 0; x < w; x++) {
      let r = br, g = bg, b = bb;

      for (const o of orbs) {
        const dx = (x - o.cx) / o.r;
        const dy = (y - o.cy) / o.r;
        const d2 = dx * dx + dy * dy;
        if (d2 < 1.8) {
          const fall = Math.exp(-2.1 * d2) * o.amp;
          r += Math.round((o.col[0] - r) * fall);
          g += Math.round((o.col[1] - g) * fall);
          b += Math.round((o.col[2] - b) * fall);
        }
      }

      if (((y / 3) | 0) % 2 === 0) {
        r = Math.round(r * 0.99);
        g = Math.round(g * 0.99);
        b = Math.round(b * 0.99);
      }

      const n = Math.round(rand(-10, 10));
      r = clamp(r + n, 0, 255);
      g = clamp(g + n, 0, 255);
      b = clamp(b + n, 0, 255);

      const vx = x / (w - 1) - 0.5;
      const vy = y / (h - 1) - 0.5;
      let v = 1.0 - 0.95 * (vx * vx + vy * vy);
      v = clamp(v, 0.35, 1.0);
      r = clamp(Math.round(r * v), 0, 255);
      g = clamp(Math.round(g * v), 0, 255);
      b = clamp(Math.round(b * v), 0, 255);

      pixels[y * w + x] = [r, g, b];
    }
  }

  return pixels;
}

