      b = clamp(Math.round(b * v), 0, 255);

      pixels[y * w + x] = [r, g, b];
    }
  }

  return pixels;
}

function makePPM(rel, w, h, seed) {
  const p = path.join('output', 'assets', rel);
  const pixels = renderAbstract(w, h, seed);
  writePPM(p, w, h, pixels);
}

